/* Recent market candles are independent of the long-term model snapshot. */
(() => {
 const el=id=>document.getElementById(id), msDay=86400000;
 const ranges={'1D':{days:1,gran:300},'1W':{days:7,gran:3600},'1M':{days:30,gran:21600},'1Y':{days:365,gran:86400}};
 const s={range:'1D',mode:'line',candles:[],from:0,to:0,loaded:false,source:'',fetched:0,quote:null,quoteLive:false,meta:null,request:0,selections:[],hovered:null,cache:{}};
 const fmt=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v);
 const stamp=t=>new Date(t).toLocaleString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' UTC';
 const axis=(x,y,label,anchor='start')=>`<text x="${x}" y="${y}" fill="#758295" font-family="IBM Plex Mono,monospace" font-size="10" text-anchor="${anchor}">${label}</text>`;
 function normalize(rows){const map=new Map();for(const r of rows){if(!Array.isArray(r)||r.length<6)continue;const [seconds,low,high,open,close,volume]=r.map(Number);if(![seconds,low,high,open,close,volume].every(Number.isFinite)||Math.min(low,high,open,close)<=0||high<low||open<low||open>high||close<low||close>high||volume<0)continue;map.set(seconds,{t:seconds*1000,low,high,open,close,volume});}return [...map.values()].sort((a,b)=>a.t-b.t);}
 function rawRows(candles){return candles.map(p=>[p.t/1000,p.low,p.high,p.open,p.close,p.volume]);}
 async function recentCandles(range){const conf=ranges[range],end=Date.now(),start=end-conf.days*msDay,maxSpan=conf.gran*290000;const chunks=[];for(let t=start;t<end;t+=maxSpan){const params=new URLSearchParams({granularity:conf.gran,start:new Date(t).toISOString(),end:new Date(Math.min(end,t+maxSpan)).toISOString()});chunks.push(fetch('https://api.exchange.coinbase.com/products/BTC-USD/candles?'+params,{signal:AbortSignal.timeout(14000)}).then(async r=>{if(!r.ok)throw Error('Candle request failed');const rows=await r.json();if(!Array.isArray(rows))throw Error('Invalid candles');return rows}));}const rows=(await Promise.all(chunks)).flat(),candles=normalize(rows).filter(p=>p.t>=start-conf.gran*1000&&p.t<=end);if(candles.length<2)throw Error('No recent candles');return candles;}
 async function savedCandles(range){try{const cached=JSON.parse(localStorage.getItem('observatory-candles-'+range));if(cached&&Array.isArray(cached.rows)){const candles=normalize(cached.rows);if(candles.length>1)return {candles,fetched:cached.fetched,source:'Cached candles'};}}catch{}const r=await fetch('spot-snapshot.json');if(!r.ok)throw Error('Snapshot unavailable');const json=await r.json(),candles=normalize(json.ranges[range]||[]);if(candles.length<2)throw Error('No saved candles');return {candles,fetched:Date.parse(json.fetched),source:'Saved market snapshot'};}
 async function load(reset=true){const range=s.range,id=++s.request;el('spot-loading').textContent='Loading '+range+' market candles…';el('spot-loading').hidden=!reset&&s.loaded;el('spot-badge').textContent='UPDATING';let result;
 try{const candles=await recentCandles(range);result={candles,fetched:Date.now(),source:'Coinbase Exchange'};try{localStorage.setItem('observatory-candles-'+range,JSON.stringify({rows:rawRows(candles),fetched:result.fetched}))}catch{}}
 catch{try{result=await savedCandles(range)}catch{if(id!==s.request)return;el('spot-loading').hidden=false;el('spot-loading').textContent='Market candles unavailable. Use Refresh data to retry.';el('spot-badge').textContent='UNAVAILABLE';el('spot-status').textContent='Could not load '+range+' candles';s.loaded=false;s.candles=[];s.meta=null;el('spot-chart').innerHTML='';for(const id of ['spot-price','spot-change','spot-high','spot-low'])el(id).textContent='—';hide();return;}}
 if(id!==s.request)return;const oldLast=s.candles.at(-1)?.t;s.candles=result.candles;s.source=result.source;s.fetched=result.fetched;s.loaded=true;s.cache[range]=result;
 const last=s.candles.at(-1).t;if(reset||!oldLast){s.from=s.candles[0].t;s.to=last;}else if(s.to>=oldLast-ranges[range].gran*1000){const span=s.to-s.from;s.to=last;s.from=Math.max(s.candles[0].t,last-span);}
 el('spot-loading').hidden=true;el('spot-badge').textContent=result.source==='Coinbase Exchange'?'MARKET DATA':'SAVED DATA';el('spot-badge').classList.toggle('saved-badge',result.source!=='Coinbase Exchange');el('spot-status-dot').classList.toggle('stale-dot',result.source!=='Coinbase Exchange');el('spot-status').textContent=(result.source==='Coinbase Exchange'?'Coinbase Exchange · Updated ':'Historical fallback · ')+stamp(result.fetched)+' · '+(ranges[range].gran<3600?(ranges[range].gran/60)+'m':ranges[range].gran<86400?(ranges[range].gran/3600)+'h':'1d')+' candles';draw();
 }
 function actualQuote(){const last=s.candles.at(-1);if(!last)return null;return s.quoteLive&&s.quote&&s.quote.time-last.t<Math.max(ranges[s.range].gran*1000*2,1800000)&&s.quote.time>=last.t?s.quote:null;}
 function summary(){if(!s.candles.length)return;const quote=actualQuote(),price=quote?.price||s.candles.at(-1).close,first=s.candles[0].open,change=(price/first-1)*100;el('spot-price').textContent=fmt(price);el('spot-change').textContent=(change>=0?'+':'')+change.toFixed(2)+'%';el('spot-change').classList.toggle('negative',change<0);el('spot-change-label').textContent=s.range+' · vs first candle open';el('spot-high').textContent=fmt(Math.max(...s.candles.map(p=>p.high),quote?.price||0));el('spot-low').textContent=fmt(Math.min(...s.candles.map(p=>p.low),quote?.price||Infinity));}
 function draw(){if(!s.loaded||!s.candles.length)return;summary();updateSelection();const mobile=window.innerWidth<720,W=mobile?650:1100,H=350,left=12,right=mobile?88:96,top=17,bottom=38,pw=W-left-right,ph=H-top-bottom,visible=s.candles.filter(p=>p.t>=s.from&&p.t<=s.to);if(!visible.length)return;const quote=actualQuote(),last=s.candles.at(-1),showQuote=quote&&s.to>=last.t-ranges[s.range].gran*1000;if(showQuote&&Math.floor(quote.time/(ranges[s.range].gran*1000))===Math.floor(last.t/(ranges[s.range].gran*1000))){const index=visible.findIndex(p=>p.t===last.t);if(index>=0)visible[index]={...last,close:quote.price,high:Math.max(last.high,quote.price),low:Math.min(last.low,quote.price)};}let low=Math.min(...visible.map(p=>p.low)),high=Math.max(...visible.map(p=>p.high));if(showQuote){low=Math.min(low,quote.price);high=Math.max(high,quote.price);}for(const p of s.selections){if(p.t>=s.from&&p.t<=s.to){low=Math.min(low,p.close);high=Math.max(high,p.close);}}const pad=Math.max((high-low)*.12,high*.001);low-=pad;high+=pad;const x=t=>left+(t-s.from)/(s.to-s.from||1)*pw,y=p=>top+(high-p)/(high-low)*ph;let out=`<defs><linearGradient id="spot-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f6a13b" stop-opacity=".20"/><stop offset="1" stop-color="#f6a13b" stop-opacity=".01"/></linearGradient><clipPath id="spot-clip"><rect x="${left}" y="${top}" width="${pw}" height="${ph}"/></clipPath></defs>`;
 for(let i=0;i<5;i++){const p=low+(high-low)*i/4,yy=y(p);out+=`<line x1="${left}" x2="${left+pw}" y1="${yy}" y2="${yy}" stroke="#28313e" stroke-dasharray="3 5"/>`+axis(W-right+12,yy+3,'$'+p.toLocaleString('en-US',{maximumFractionDigits:0}));}
 for(let i=0;i<=5;i++){const t=s.from+(s.to-s.from)*i/5,xx=x(t),label=(s.to-s.from)<2*msDay?new Date(t).toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'}):new Date(t).toLocaleDateString('en-GB',{timeZone:'UTC',month:'short',day:'2-digit'});out+=axis(xx,H-11,label,i===0?'start':i===5?'end':'middle');}
 out+='<g clip-path="url(#spot-clip)">';
 if(s.mode==='line'){const path=visible.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(2)},${y(p.close).toFixed(2)}`).join(' ');out+=`<path d="${path} L${x(visible.at(-1).t)},${top+ph} L${x(visible[0].t)},${top+ph} Z" fill="url(#spot-fill)"/><path d="${path}" stroke="#f6a13b" fill="none" stroke-width="1.9" stroke-linejoin="round" stroke-linecap="round"/>`;}
 else{const width=Math.max(1,Math.min(18,ranges[s.range].gran*1000/(s.to-s.from)*pw*.65));for(const p of visible){const xx=x(p.t),up=p.close>=p.open,color=up?'#83d5a3':'#df7d7d';out+=`<line x1="${xx}" x2="${xx}" y1="${y(p.high)}" y2="${y(p.low)}" stroke="${color}" stroke-width="1"/><rect x="${xx-width/2}" y="${Math.min(y(p.open),y(p.close))}" width="${width}" height="${Math.max(1,Math.abs(y(p.open)-y(p.close)))}" fill="${color}" rx=".5"/>`;}}
 out+='</g>';out+=selectionSVG(x,y,left,pw,top,ph);const latest=showQuote?quote.price:visible.at(-1).close,yy=y(latest);out+=`<line x1="${left}" x2="${left+pw}" y1="${yy}" y2="${yy}" stroke="#f6a13b" stroke-dasharray="4 5" opacity=".4"/><rect x="${W-right+5}" y="${yy-11}" width="${right-9}" height="22" rx="3" fill="#f6a13b"/><text x="${W-right/2}" y="${yy+3}" text-anchor="middle" font-family="IBM Plex Mono,monospace" font-size="10" fill="#141820">$${latest.toLocaleString('en-US',{maximumFractionDigits:0})}</text><g id="spot-crosshair" style="display:none"><line id="spot-cross-x" y1="${top}" y2="${top+ph}" stroke="#718094" stroke-dasharray="3 4"/><line id="spot-cross-y" x1="${left}" x2="${left+pw}" stroke="#718094" stroke-dasharray="3 4" opacity=".6"/><circle id="spot-cross-dot" r="3" fill="#f6a13b" stroke="#111419" stroke-width="2"/></g>`;
 el('spot-chart').setAttribute('viewBox',`0 0 ${W} ${H}`);el('spot-chart').innerHTML=out;s.meta={W,H,left,pw,x,y,visible,top,ph};el('spot-chart').setAttribute('aria-label',`${s.range} Bitcoin ${s.mode==='line'?'line':'candlestick'} chart. ${visible.length} visible candles. Price ${fmt(latest)}. Scroll or pinch to zoom, drag to pan, click to pin and compare. Plus/minus zoom, arrows pan, Enter selects, Escape clears.`);
 }
 function clampView(from,to){const first=s.candles[0]?.t,last=s.candles.at(-1)?.t;if(first===undefined)return;const span=Math.min(last-first,Math.max(ranges[s.range].gran*1000*8,to-from));if(from<first)from=first;if(from+span>last)from=last-span;s.from=from;s.to=from+span;draw();}
 function hide(){s.hovered=null;el('spot-tooltip').hidden=true;const cross=el('spot-crosshair');if(cross)cross.style.display='none';}
 function eventPoint(event){if(!s.meta)return null;if(!event){if(s.hovered&&s.hovered.t>=s.from&&s.hovered.t<=s.to)return s.hovered;return s.meta.visible[Math.floor(s.meta.visible.length/2)];}const r=el('spot-chart').getBoundingClientRect();if(!r.width)return null;const xx=(event.clientX-r.left)/r.width*s.meta.W;if(xx<s.meta.left||xx>s.meta.left+s.meta.pw)return null;const t=s.from+(xx-s.meta.left)/s.meta.pw*(s.to-s.from);return s.meta.visible.reduce((a,b)=>Math.abs(b.t-t)<Math.abs(a.t-t)?b:a);}
 function hover(event){const p=eventPoint(event);if(!p){hide();return;}s.hovered=p;const m=s.meta,cx=m.x(p.t),cy=m.y(p.close);el('spot-crosshair').style.display='';el('spot-cross-x').setAttribute('x1',cx);el('spot-cross-x').setAttribute('x2',cx);el('spot-cross-y').setAttribute('y1',cy);el('spot-cross-y').setAttribute('y2',cy);el('spot-cross-dot').setAttribute('cx',cx);el('spot-cross-dot').setAttribute('cy',cy);const tooltip=el('spot-tooltip');tooltip.innerHTML=`<strong>${stamp(p.t)}</strong><p>Open <b>${fmt(p.open)}</b></p><p>High <b>${fmt(p.high)}</b></p><p>Low <b>${fmt(p.low)}</b></p><p>Close <b>${fmt(p.close)}</b></p><p>Volume <b>${p.volume.toFixed(2)} BTC</b></p><small>Click or tap to pin this price</small>`;tooltip.hidden=false;const c=el('spot-chart-container').getBoundingClientRect();tooltip.style.left=Math.min(Math.max(8,event.clientX-c.left+15),Math.max(8,c.width-tooltip.offsetWidth-8))+'px';tooltip.style.top=Math.min(Math.max(8,event.clientY-c.top-70),Math.max(8,c.height-tooltip.offsetHeight-8))+'px';}
 function selectionSVG(x,y,left,pw,top,ph){let out='<g id="spot-selection-markers" clip-path="url(#spot-clip)">';if(s.selections.length===2){const a=Math.max(left,Math.min(x(s.selections[0].t),x(s.selections[1].t))),b=Math.min(left+pw,Math.max(x(s.selections[0].t),x(s.selections[1].t)));if(b>a)out+=`<rect x="${a}" y="${top}" width="${b-a}" height="${ph}" fill="#6c97de" opacity=".07"/>`;}s.selections.forEach((p,i)=>{if(p.t<s.from||p.t>s.to)return;const cx=x(p.t),cy=y(p.close),color=i?'#6c97de':'#f6a13b';out+=`<line x1="${cx}" x2="${cx}" y1="${top}" y2="${top+ph}" stroke="${color}" stroke-dasharray="4 4" opacity=".8"/><circle cx="${cx}" cy="${cy}" r="5" fill="#111419" stroke="${color}" stroke-width="2"/><rect x="${cx-8}" y="${top+4}" width="16" height="17" rx="3" fill="${color}"/><text x="${cx}" y="${top+16}" text-anchor="middle" fill="#111419" font-family="IBM Plex Mono,monospace" font-size="10">${i?'B':'A'}</text>`;});return out+'</g>';}
 function updateSelection(){const first=s.selections[0];el('spot-inspector').hidden=!first;el('spot-selection-hint').hidden=!!first;if(!first)return;el('spot-selected-date').textContent=stamp(first.t);for(const field of ['close','open','high','low'])el('spot-selected-'+field).textContent=fmt(first[field]);el('spot-selected-volume').textContent=first.volume.toFixed(2)+' BTC';const second=s.selections[1];if(!second){el('spot-comparison').textContent='Price A pinned. Click another price to compare.';return;}const diff=second.close-first.close,percent=(second.close/first.close-1)*100,sign=diff>=0?'+':'−',minutes=Math.abs(second.t-first.t)/60000,duration=minutes>=1440?(minutes/1440).toFixed(1)+' days':minutes>=60?(minutes/60).toFixed(1)+' hours':Math.round(minutes)+' minutes';el('spot-comparison').innerHTML=`<span><b>A → B</b> · ${stamp(second.t)} · ${fmt(second.close)}</span><strong class="${diff<0?'negative-change':'positive-change'}">${sign}${fmt(Math.abs(diff))} (${percent>=0?'+':''}${percent.toFixed(2)}%)</strong><span>${duration} apart · Click a price to start a new comparison.</span>`;}
 function selectPoint(event){const p=eventPoint(event);if(!p)return;if(s.selections.length===2)s.selections=[];if(s.selections.length===1&&s.selections[0].t===p.t)return;s.selections.push({...p});hide();draw();}
 function clearSelection(){s.selections=[];s.hovered=null;hide();draw();}
 function reset(){if(!s.candles.length)return;s.from=s.candles[0].t;s.to=s.candles.at(-1).t;draw();hide();}
 const gestures=bindChartGestures(el('spot-chart'),{getView:()=>({from:s.from,to:s.to}),getMeta:()=>s.loaded?s.meta:null,setView:clampView,onHover:hover,onLeave:hide,onSelect:selectPoint,onClear:clearSelection,onReset:reset});
 el('spot-clear-selection').addEventListener('click',clearSelection);
 el('spot-zoom-in').addEventListener('click',()=>gestures.zoom(.7));el('spot-zoom-out').addEventListener('click',()=>gestures.zoom(1.4));el('spot-reset').addEventListener('click',reset);
 document.querySelectorAll('[data-spot-range]').forEach(b=>b.addEventListener('click',()=>{s.range=b.dataset.spotRange;s.selections=[];s.hovered=null;updateSelection();document.querySelectorAll('[data-spot-range]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});hide();load(true)}));
 document.querySelectorAll('[data-spot-mode]').forEach(b=>b.addEventListener('click',()=>{s.mode=b.dataset.spotMode;document.querySelectorAll('[data-spot-mode]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});draw();hide()}));
 el('spot-export').addEventListener('click',()=>{if(!s.candles.length)return;const csv=['time_utc,open_usd,high_usd,low_usd,close_usd,volume_btc',...s.candles.map(p=>[new Date(p.t).toISOString(),p.open,p.high,p.low,p.close,p.volume].join(','))].join('\n');exportFile('bitcoin-spot-'+s.range+'.csv',csv,'text/csv');notify('Market candles exported as CSV.')});
 window.onSpotQuote=(quote,live)=>{s.quote=quote;s.quoteLive=live;draw()};window.refreshSpot=()=>load(false);window.redrawSpot=draw;
 let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(draw,100)});
 load(true);setInterval(()=>{if(!document.hidden)load(false)},60000);
})();
